SELECT CASE WHEN quantity >= 213 THEN 'high' WHEN quantity >= 69 THEN 'mid' ELSE 'low' END AS quantity_bucket, DATE_FORMAT(last_restock, 'yyyy-MM') AS last_restock_month, MAX(last_restock) AS last_last_restock, COUNT(*) AS inventory_count FROM inventory WHERE store_id IN (3, 5) GROUP BY ROLLUP(CASE WHEN quantity >= 213 THEN 'high' WHEN quantity >= 69 THEN 'mid' ELSE 'low' END, DATE_FORMAT(last_restock, 'yyyy-MM')) ORDER BY 4
